g=[[4]*9 for _ in range(19)]
rows=[[0,1,4,5],[0],[2,3,4,5],[5],[0,5],[0,5],[0,3,5]]
for i,cs in enumerate(rows,start=2):
 for c in cs:g[i][c]=3
# all gaps between original matching cells along rows/cols
out=[r[:] for r in g]
for r in range(19):
 cs=[c for c,x in enumerate(g[r]) if x==3]
 for a,b in zip(cs,cs[1:]):
  for c in range(a+1,b):out[r][c]=2
for c in range(9):
 rs=[r for r in range(19) if g[r][c]==3]
 for a,b in zip(rs,rs[1:]):
  for r in range(a+1,b):out[r][c]=2
[(i,[c for c in range(9) if out[i][c]==2]) for i in range(19) if 2 in out[i]]
